// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 initialDeposit, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(initialDeposit > 0);
        vm.assume(withdrawAmount <= initialDeposit);

        vm.deal(actor, initialDeposit);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: initialDeposit}("");
        require(ok, "deposit failed");

        uint256 balanceBefore = c.balances(actor);
        vm.prank(actor);
        (bool wOk, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        if (!wOk) {
            assertTrue(true);
            return;
        }

        uint256 balanceAfter = c.balances(actor);
        assertTrue(balanceAfter == 0);
    }
}
